def wire(a, b, sag=0.35, r=0.012):
    pts = []
    for k in range(9):
        t = k / 8
        p = lerp(a, b, t)
        pts.append((p[0], p[1] - sag * math.sin(math.pi * t), p[2]))
    for p, q in zip(pts, pts[1:]):
        pole(p, q, r, 'wire', seg=4, name='wire')


